import React, { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '../providers/auth'

const Dashboard = () => {
  const { user, logout } = useAuth()
  const navigate = useNavigate()

  const [meetings, setMeetings] = useState([])
  const [meetingName, setMeetingName] = useState('')
  const [meetingDate, setMeetingDate] = useState('')
  const [meetingTime, setMeetingTime] = useState('')
  const [copiedIndex, setCopiedIndex] = useState(null)

  // Past meetings mock database
  const pastMeetings = [
    {
      id: 'past-1',
      name: 'Q3 Product Strategy Alignment',
      date: '2026-07-20',
      duration: '45 mins',
      participants: ['Anuj Katare', 'Sarah Lin', 'AI Assistant'],
      summary: 'Reviewed WebRTC audio optimization. AI Assistant suggested a speech transcription latency of <100ms. Decided to upgrade UI with ElevenLabs print style.',
      cloudLink: '#recording'
    },
    {
      id: 'past-2',
      name: 'Speech Translation Research Review',
      date: '2026-07-18',
      duration: '32 mins',
      participants: ['Anuj Katare', 'Dr. Aris (ElevenLabs)', 'AI Assistant'],
      summary: 'Discussed MediaPipe hands SDK. Identified gesture raised-hand trigger duration of 2.0 seconds is ideal to prevent false positives.',
      cloudLink: '#recording'
    }
  ]

  useEffect(() => {
    if (!user) {
      navigate('/auth')
      return
    }

    // Load scheduled meetings from local storage
    const savedMeetings = localStorage.getItem(`meetings_${user.profileId}`)
    if (savedMeetings) {
      try {
        setMeetings(JSON.parse(savedMeetings))
      } catch (e) {
        console.error(e)
      }
    }
  }, [user, navigate])

  const saveMeetings = (updated) => {
    setMeetings(updated)
    if (user) {
      localStorage.setItem(`meetings_${user.profileId}`, JSON.stringify(updated))
    }
  }

  const handleCreateInstantMeeting = () => {
    // Generate a random slug e.g. abc-defg-hij
    const slug = `${Math.random().toString(36).substr(2, 3)}-${Math.random().toString(36).substr(2, 4)}-${Math.random().toString(36).substr(2, 3)}`

    // Add to scheduled list or navigate directly
    navigate(`/room/${slug}`)
  }

  const handleScheduleMeeting = (e) => {
    e.preventDefault()
    if (!meetingName || !meetingDate || !meetingTime) {
      alert('Please fill out all fields')
      return
    }

    const slug = `${Math.random().toString(36).substr(2, 3)}-${Math.random().toString(36).substr(2, 4)}-${Math.random().toString(36).substr(2, 3)}`
    const newMeeting = {
      id: Math.random().toString(36).substr(2, 9),
      name: meetingName,
      date: meetingDate,
      time: meetingTime,
      slug,
    }

    const updated = [newMeeting, ...meetings]
    saveMeetings(updated)

    setMeetingName('')
    setMeetingDate('')
    setMeetingTime('')
  }

  const handleCopyLink = (slug, index) => {
    const fullLink = `${window.location.origin}/room/${slug}`
    navigator.clipboard.writeText(fullLink)
    setCopiedIndex(index)
    setTimeout(() => setCopiedIndex(null), 2000)
  }

  const handleDeleteMeeting = (id) => {
    const updated = meetings.filter(m => m.id !== id)
    saveMeetings(updated)
  }

  const handleAddToCalendar = (meeting) => {
    const title = encodeURIComponent(meeting.name)
    const dates = encodeURIComponent(`${meeting.date.replace(/-/g, '')}T${meeting.time.replace(/:/g, '')}00Z`)
    const details = encodeURIComponent(`Join AuraChat session here: ${window.location.origin}/room/${meeting.slug}`)
    const gCalUrl = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${title}&dates=${dates}/${dates}&details=${details}&sf=true&output=xml`
    window.open(gCalUrl, '_blank')
  }

  if (!user) return null

  return (
    <div style={{ minHeight: '100vh', backgroundColor: 'var(--color-canvas)', position: 'relative', overflowX: 'hidden' }}>
      {/* Background decoration orbs */}
      <div className="gradient-orb-container">
        <div className="gradient-orb orb-sky" style={{ top: '-10%', right: '10%' }}></div>
        <div className="gradient-orb orb-rose" style={{ bottom: '-15%', left: '5%' }}></div>
      </div>

      {/* Top Nav */}
      <header className="top-nav">
        <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--spacing-xs)' }}>
          <h2 className="font-display" style={{ fontSize: '24px', letterSpacing: '-0.5px' }}>AuraChat</h2>
          <span className="badge-pill" style={{ fontSize: '10px' }}>Beta</span>
        </div>
        <nav style={{ display: 'flex', alignItems: 'center', gap: 'var(--spacing-xl)' }}>
          <ul className="nav-links" style={{ display: 'flex', gap: 'var(--spacing-lg)' }}>
            <li><a className="nav-link" onClick={() => navigate('/')}>Home</a></li>
            <li><a className="nav-link" style={{ fontWeight: 600 }}>Workspace</a></li>
            <li><a className="nav-link" href="https://elevenlabs.io/docs" target="_blank" rel="noopener noreferrer">Docs</a></li>
          </ul>
        </nav>
        <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--spacing-md)' }}>
          <span className="body-strong" style={{ fontSize: '14px' }}>{user.name}</span>
          <button className="button-outline" onClick={logout} style={{ height: '36px', padding: '0 16px', fontSize: '14px' }}>
            Sign Out
          </button>
        </div>
      </header>

      {/* Workspace Dashboard Grid */}
      <main className="container-wide" style={{ position: 'relative', zIndex: 10, padding: 'var(--spacing-xl) var(--spacing-lg)' }}>
        <h1 className="font-display display-lg" style={{ marginBottom: 'var(--spacing-lg)' }}>
          Your Collaboration Hub
        </h1>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 'var(--spacing-xl)', marginBottom: 'var(--spacing-xl)' }}>

          {/* Left Column: Create & Schedule */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--spacing-xl)' }}>

            {/* Quick Action Card */}
            <div className="feature-card" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--spacing-base)' }}>
              <span className="badge-pill" style={{ width: 'fit-content' }}>Instant Call</span>
              <h2 className="font-display display-sm">Start a meeting right away</h2>
              <p className="body-md">Create a room instantly, generate host approval credentials, and invite external guests.</p>
              <button className="button-primary" onClick={handleCreateInstantMeeting} style={{ width: 'fit-content' }}>
                New Meeting Room
              </button>
            </div>

            {/* Scheduler Card */}
            <div className="feature-card">
              <span className="badge-pill" style={{ width: 'fit-content', marginBottom: 'var(--spacing-sm)' }}>Schedule</span>
              <h2 className="font-display display-sm" style={{ marginBottom: 'var(--spacing-xs)' }}>Plan a Future Session</h2>
              <p className="body-md" style={{ marginBottom: 'var(--spacing-base)' }}>Schedule a custom room name and send automated invites.</p>

              <form onSubmit={handleScheduleMeeting} style={{ display: 'flex', flexDirection: 'column', gap: 'var(--spacing-sm)' }}>
                <input
                  type="text"
                  placeholder="Meeting Topic (e.g. Marketing Standup)"
                  className="text-input"
                  value={meetingName}
                  onChange={(e) => setMeetingName(e.target.value)}
                  required
                />
                <div style={{ display: 'flex', gap: 'var(--spacing-sm)' }}>
                  <input
                    type="date"
                    className="text-input"
                    value={meetingDate}
                    onChange={(e) => setMeetingDate(e.target.value)}
                    required
                  />
                  <input
                    type="time"
                    className="text-input"
                    value={meetingTime}
                    onChange={(e) => setMeetingTime(e.target.value)}
                    required
                  />
                </div>
                <button type="submit" className="button-outline" style={{ marginTop: 'var(--spacing-xs)' }}>
                  Schedule Meeting
                </button>
              </form>
            </div>
          </div>

          {/* Right Column: Upcoming Meetings */}
          <div className="feature-card" style={{ display: 'flex', flexDirection: 'column', minHeight: '440px' }}>
            <span className="badge-pill" style={{ width: 'fit-content', marginBottom: 'var(--spacing-sm)' }}>Schedule Queue</span>
            <h2 className="font-display display-sm" style={{ marginBottom: 'var(--spacing-sm)' }}>Upcoming Scheduled Meetings</h2>

            {meetings.length === 0 ? (
              <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', border: '1px dashed var(--color-hairline-strong)', borderRadius: 'var(--rounded-lg)', padding: 'var(--spacing-xl)' }}>
                <p className="body-md" style={{ color: 'var(--color-muted)' }}>No meetings scheduled yet. Use the scheduler to set one up.</p>
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--spacing-base)', overflowY: 'auto', maxHeight: '420px', paddingRight: '4px' }}>
                {meetings.map((m, i) => (
                  <div key={m.id} className="voice-row" style={{ flexDirection: 'column', alignItems: 'stretch', padding: 'var(--spacing-sm)', border: '1px solid var(--color-hairline)', borderRadius: 'var(--rounded-lg)', backgroundColor: 'var(--color-canvas-soft)' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 'var(--spacing-xs)' }}>
                      <div>
                        <h4 className="title-sm" style={{ fontWeight: 600 }}>{m.name}</h4>
                        <p className="body-sm" style={{ fontSize: '13px', color: 'var(--color-muted)' }}>
                          {m.date} at {m.time}
                        </p>
                      </div>
                      <button 
                        onClick={() => handleDeleteMeeting(m.id)} 
                        style={{ background: 'none', border: 'none', color: 'var(--color-error)', cursor: 'pointer', fontSize: '13px' }}
                      >
                        Cancel
                      </button>
                    </div>

                    <div style={{ display: 'flex', gap: 'var(--spacing-xs)', marginTop: 'var(--spacing-xs)' }}>
                      <button 
                        className="button-primary" 
                        onClick={() => navigate(`/room/${m.slug}`)} 
                        style={{ height: '32px', fontSize: '13px', padding: '0 14px' }}
                      >
                        Start Meeting
                      </button>
                      <button 
                        className="button-outline" 
                        onClick={() => handleCopyLink(m.slug, i)} 
                        style={{ height: '32px', fontSize: '13px', padding: '0 14px' }}
                      >
                        {copiedIndex === i ? 'Copied ✓' : 'Copy Invite Link'}
                      </button>
                      <button 
                        className="button-outline" 
                        onClick={() => handleAddToCalendar(m)} 
                        style={{ height: '32px', fontSize: '13px', padding: '0 10px' }}
                      >
                        Calendar 📅
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Bottom Section: Past Meetings History */}
        <div className="feature-card">
          <span className="badge-pill" style={{ width: 'fit-content', marginBottom: 'var(--spacing-sm)' }}>Logs</span>
          <h2 className="font-display display-sm" style={{ marginBottom: 'var(--spacing-md)' }}>Past Meetings & AI Summaries</h2>

          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--spacing-lg)' }}>
            {pastMeetings.map((p) => (
              <div key={p.id} style={{ borderBottom: '1px solid var(--color-hairline)', paddingBottom: 'var(--spacing-md)' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 'var(--spacing-xs)' }}>
                  <h3 className="title-sm" style={{ fontWeight: 600 }}>{p.name}</h3>
                  <span className="caption">{p.date} • {p.duration}</span>
                </div>
                <div style={{ display: 'flex', gap: 'var(--spacing-xs)', flexWrap: 'wrap', marginBottom: 'var(--spacing-xs)' }}>
                  {p.participants.map((participant, index) => (
                    <span key={index} className="badge-pill" style={{ textTransform: 'none', fontWeight: 500, fontSize: '11px', backgroundColor: 'var(--color-surface-strong)' }}>
                      {participant}
                    </span>
                  ))}
                </div>
                <p className="body-sm" style={{ color: 'var(--color-body)', marginBottom: 'var(--spacing-sm)' }}>
                  <strong>AI Summary:</strong> {p.summary}
                </p>
                <div style={{ display: 'flex', gap: 'var(--spacing-sm)' }}>
                  <button className="button-outline" style={{ height: '28px', padding: '0 12px', fontSize: '12px' }} onClick={() => alert('Downloading audio transcription file...')}>
                    Transcript TXT
                  </button>
                  <button className="button-outline" style={{ height: '28px', padding: '0 12px', fontSize: '12px' }} onClick={() => alert('Accessing cloud stream recording (mock)...')}>
                    Play Recording 🎬
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </main>
    </div>
  )
}

export default Dashboard
